const SURVEY_OPTIONS = Object.freeze({goal:['Сдать IELTS','Изучать General English','Поступить за рубеж','Английский для работы и общения','Помогите определиться'],level:['С нуля','Начальный (A1–A2)','Средний (B1–B2)','Продвинутый (C1–C2)','Не знаю — определим на уроке'],start:['Как можно скорее','В течение месяца','Позже — пока выбираю']});
const SURVEY_LABELS = Object.freeze({goal:'Цель',level:'Уровень',start:'Когда начать'});
function cleanSurvey(input){const value=input&&typeof input==='object'?input:{};return Object.fromEntries(Object.entries(SURVEY_OPTIONS).filter(([key,options])=>options.includes(value[key])).map(([key])=>[key,value[key]]));}
function surveyLines(input){return Object.entries(cleanSurvey(input)).map(([key,value])=>SURVEY_LABELS[key]+': '+value);}
const TRACKING_KEYS = Object.freeze(['utm_content','utm_medium','utm_campaign','utm_source','utm_term','utm_referrer','roistat','referrer','openstat_service','openstat_campaign','openstat_ad','openstat_source','from','gclientid','_ym_uid','_ym_counter','gclid','yclid','fbclid']);
const TTL = 90 * 86400000;
const STORAGE_KEY = 'smartclass.attribution.v1';
function cleanTracking(input) {
 const source=input&&typeof input==='object'&&!Array.isArray(input)?input:{};
 return Object.fromEntries(TRACKING_KEYS.filter(k=>typeof source[k]==='string'&&source[k].trim()).map(k=>[k,source[k].trim().replace(/[\u0000-\u001f\u007f]/g,'').slice(0,k.includes('referrer')?2048:512)]));
}
function captureAttribution({url,referrer='',cookies='',previous=null,now=Date.now(),counterId=''}){
 const page=new URL(url),params=page.searchParams,values={},jar={};
 for(const key of TRACKING_KEYS)if(params.get(key))values[key]=params.get(key);
 for(const item of cookies.split(';').filter(Boolean)){const i=item.indexOf('=');if(i<0)continue;let v=item.slice(i+1);try{v=decodeURIComponent(v)}catch{}jar[item.slice(0,i).trim()]=v;}
 const fill=(k,v)=>{if(!values[k]&&v)values[k]=v};
 fill('roistat',jar.roistat_visit);fill('_ym_uid',jar._ym_uid);fill('_ym_counter',counterId);
 if(jar._ga){const bits=jar._ga.split('.');if(bits.length>=4)fill('gclientid',bits.slice(-2).join('.'));}
 const openstat=params.get('_openstat');if(openstat){try{const p=atob(openstat.replace(/ /g,'+')).split(';');['openstat_service','openstat_campaign','openstat_ad','openstat_source'].forEach((k,i)=>fill(k,p[i]));}catch{}}
 let external='';try{const r=new URL(referrer);if(r.origin!==page.origin)external=r.href;}catch{}
 fill('referrer',external);fill('utm_referrer',external);
 const valid=previous?.version===1&&previous.last&&previous.first&&now-previous.updatedAt<TTL&&now>=previous.updatedAt;
 const isCampaign=['utm_source','utm_medium','utm_campaign','utm_content','utm_term','gclid','yclid','fbclid','from','_openstat','roistat','openstat_campaign'].some(k=>params.get(k));
 const fresh=cleanTracking(values);
 const last=valid&&!isCampaign?cleanTracking({...previous.last,...Object.fromEntries(Object.entries(fresh).filter(([k])=>!k.includes('referrer')))}):fresh;
 const landing=/^https?:$/.test(page.protocol)?page.origin+page.pathname:'';
 return {version:1,first:valid?cleanTracking(previous.first):fresh,last,firstLanding:valid?previous.firstLanding:landing,landing,updatedAt:now};
}
function normalizePhone(value){let d=String(value||'').replace(/\D/g,'');if(d.length===11&&d[0]==='8')d='7'+d.slice(1);return /^[1-9]\d{9,14}$/.test(d)?'+'+d:null;}
function whatsappURL({name='',course='Подбор программы',branch='',survey={},tracking={},landing='',reference=''},number='77085427588'){
 const lines=['Здравствуйте! Хочу записаться на бесплатный пробный урок в SmartClass.',`Программа: ${course}`,name?`Имя: ${name}`:'',branch?`Филиал: ${branch}`:'',reference?`Код заявки: ${reference}`:'',...surveyLines(survey),...Object.entries(cleanTracking(tracking)).map(([k,v])=>`${k}: ${v}`),landing?`Страница: ${landing}`:''].filter(Boolean);
 return `https://wa.me/${number.replace(/\D/g,'')}?text=${encodeURIComponent(lines.join('\n'))}`;
}

