const kk=new Map(pairs),ru=new Map(pairs.map(([a,b])=>[b,a]));
let language='ru';try{language=localStorage.getItem('smartclass.language')==='kk'?'kk':'ru'}catch{}
function translateText(text,lang=language){
 const trimmed=text.trim(),canonical=ru.get(trimmed)||trimmed;
 if(lang==='ru')return text.replace(trimmed,canonical);
 if(kk.has(canonical))return text.replace(trimmed,kk.get(canonical));
 if(/^Шаг \d из 4 · /.test(canonical)){const m=canonical.match(/^Шаг (\d) из 4 · (.+)$/);return `4 қадамның ${m[1]}-қадамы · ${kk.get(m[2])||m[2]}`;}
 if(/^4 қадамның \d-қадамы · /.test(trimmed))return text;
 if(canonical.startsWith('Цель: '))return canonical.split(' · ').map(line=>{const i=line.indexOf(': ');return translateText(line.slice(0,i),lang)+': '+translateText(line.slice(i+2),lang)}).join(' · ');
 return text;
}
// Remember canonical text, so repeated switching never changes form values or analytics keys.
const originals=new WeakMap(),attributes=new WeakMap();
function apply(){
 document.documentElement.lang=language;
 for(const option of document.querySelectorAll('option'))if(!option.hasAttribute('value'))option.setAttribute('value',option.textContent);
 const walker=document.createTreeWalker(document.documentElement,NodeFilter.SHOW_TEXT);let node;
 while((node=walker.nextNode())){if(node.parentElement?.closest('script,style,[data-language]'))continue;const old=originals.get(node);const canonical=old&&node.nodeValue===old.rendered?old.canonical:node.nodeValue;const rendered=translateText(canonical);originals.set(node,{canonical,rendered});if(node.nodeValue!==rendered)node.nodeValue=rendered;}
 for(const el of document.querySelectorAll('[aria-label],[placeholder],[alt],meta[name="description"],meta[property="og:title"],meta[property="og:description"]')){
  const saved=attributes.get(el)||{};for(const key of ['aria-label','placeholder','content','alt'])if(el.hasAttribute(key)){const current=el.getAttribute(key),prior=saved[key],canonical=prior&&current===prior.rendered?prior.canonical:current;const rendered=translateText(canonical);saved[key]={canonical,rendered};if(current!==rendered)el.setAttribute(key,rendered);}attributes.set(el,saved);
 }
 document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===language)));
}
document.querySelectorAll('[data-language]').forEach(button=>button.addEventListener('click',()=>{language=button.dataset.language;try{localStorage.setItem('smartclass.language',language)}catch{}apply()}));
const observer=new MutationObserver(()=>{observer.disconnect();apply();observe()});
function observe(){observer.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label']})}
apply();observe();
function registerTranslations(entries){for(const [source,target] of entries){kk.set(source,target);ru.set(target,source);}apply();}
function localizedWhatsApp(url){if(language!=='kk')return url;const value=new URL(url);value.searchParams.set('text',(value.searchParams.get('text')||'').split('\n').map(line=>{if(/^(utm_|roistat:|referrer:|openstat_|from:|gclientid:|_ym_|gclid:|yclid:|fbclid:)/.test(line))return line;const whole=translateText(line);if(whole!==line)return whole;const i=line.indexOf(': ');return i<0?translateText(line):translateText(line.slice(0,i))+': '+translateText(line.slice(i+2))}).join('\n'));return value.href;}

const JOURNEY_REMINDER_INTERVAL=90000;
function createJourneyReminderSchedule({show,isBlocked,setTimer=setTimeout,clearTimer=clearTimeout}){
 let active=true,timer;
 function tick(){if(!active)return;try{if(!isBlocked())show();}finally{if(active)timer=setTimer(tick,JOURNEY_REMINDER_INTERVAL);}}
 timer=setTimer(tick,JOURNEY_REMINDER_INTERVAL);
 return {stop(){active=false;clearTimer(timer);}};
}




function contactURL(data){return localizedWhatsApp(whatsappURL(data));}
