let previous=null;try{previous=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')}catch{}
const attribution=captureAttribution({url:location.href,referrer:document.referrer,cookies:document.cookie,previous});
try{localStorage.setItem(STORAGE_KEY,JSON.stringify(attribution))}catch{}
// Re-read accessible cookies just before submitting: analytics may load after the first render.
function tracking(){return captureAttribution({url:location.href,referrer:document.referrer,cookies:document.cookie,previous:attribution});}
function event(name,fields={}){window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:name,...fields});}
const modal=$('#booking'),form=$('#booking-form'),status=$('#form-status'),submit=$('#submit-booking'),fallback=$('#wa-fallback');
let requestId='',busy=false,quizStep=0,survey={};
const questions=[['goal','Для чего вам английский?'],['level','Какой у вас уровень?'],['start','Когда хотите начать?']];
function renderQuiz(focus=true){
 if(!busy){status.textContent='';fallback.hidden=true;submit.hidden=false;}
 const contact=quizStep===questions.length;
 $('#quiz').hidden=contact;form.hidden=!contact;
 $('#quiz-progress').textContent='Шаг '+(quizStep+1)+' из 4 · '+(contact?'Пробный урок':['Ваша цель','Текущий уровень','Удобный старт'][quizStep]);
 $('#booking-title').textContent=contact?'Осталось выбрать время.':questions[quizStep][1];
 $('#quiz-intro').textContent=contact?'Оставьте номер — администратор согласует время бесплатного пробного урока.':'Три коротких вопроса — чтобы подготовиться к вашему пробному уроку.';
 $('#quiz-back').hidden=quizStep===0;
 if(contact){$('#quiz-summary').textContent=surveyLines(survey).join(' · ');}
 else {const [key]=questions[quizStep];$('#quiz-options').replaceChildren(...SURVEY_OPTIONS[key].map(value=>{const b=document.createElement('button');b.type='button';b.className='quiz-option';b.textContent=value;b.setAttribute('aria-pressed',String(survey[key]===value));b.addEventListener('click',()=>{survey[key]=value;requestId=crypto.randomUUID();if(key==='goal'){const course={'Сдать IELTS':'IELTS','Изучать General English':'General English','Поступить за рубеж':'Поступление'}[value];if(course)$('#course').value=course;}quizStep++;event('quiz_step',{step:quizStep});renderQuiz();});return b;}));}
 modal.scrollTop=0;if(focus)$('#booking-title').focus();
}
$('#quiz-back').addEventListener('click',()=>{quizStep=Math.max(0,quizStep-1);renderQuiz()});
$('#quiz-skip').addEventListener('click',()=>{quizStep=questions.length;renderQuiz()});
$('#edit-quiz').addEventListener('click',()=>{quizStep=0;renderQuiz()});
document.querySelectorAll('[data-book]').forEach(button=>button.addEventListener('click',()=>{if(busy)return;requestId=crypto.randomUUID();$('#course').value=button.dataset.book||'Подбор программы';status.textContent='';fallback.hidden=true;submit.hidden=false;quizStep=0;renderQuiz(false);modal.showModal();$('#menu').classList.remove('open');$('#burger').setAttribute('aria-expanded','false');event('form_start',{course:$('#course').value});}));
$('#close-booking').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
$('#burger').addEventListener('click',()=>{const opened=$('#menu').classList.toggle('open');$('#burger').setAttribute('aria-expanded',String(opened));$('#burger').setAttribute('aria-label',opened?'Закрыть меню':'Открыть меню')});
document.querySelectorAll('#menu a').forEach(a=>a.addEventListener('click',()=>{$('#menu').classList.remove('open');$('#burger').setAttribute('aria-expanded','false')}));
function waPayload(extra={}){const a=tracking();return {...extra,tracking:a.last,firstTracking:a.first,landing:a.landing};}
document.querySelectorAll('[data-whatsapp]').forEach(button=>button.addEventListener('click',()=>{const url=contactURL(waPayload({reference:'SC-'+crypto.randomUUID().slice(0,8)}));event('whatsapp_click',{kind:'direct'});location.assign(url);}));
fallback.addEventListener('click',()=>event('whatsapp_click',{kind:'form'}));
form.addEventListener('input',()=>{if(!busy){requestId=crypto.randomUUID();fallback.hidden=true;submit.hidden=false;status.textContent='';}});
form.addEventListener('submit',async e=>{
 e.preventDefault();if(busy)return;if(!form.reportValidity())return;
 const fd=new FormData(form),phone=normalizePhone(fd.get('phone'));if(!phone){status.textContent='Укажите номер с кодом страны, например +7 708 123-45-67.';$('#phone').focus();return;}
 requestId=requestId||crypto.randomUUID();
 const data=waPayload({requestId,survey:{...survey},name:String(fd.get('name')||'').trim(),phone,course:String(fd.get('course')||''),branch:String(fd.get('branch')||''),consent:fd.get('consent')==='on',website:String(fd.get('website')||'')});
 const url=contactURL({...data,reference:'SC-'+requestId.slice(0,8)});
 busy=true;submit.disabled=true;status.textContent='Готовим вашу запись…';fallback.hidden=true;
 try{
  const result=await fetch('/api/leads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(30000)});
  const body=await result.json();if(!result.ok||!body.ok)throw new Error(body.code||'save_failed');
  event('lead_created',{lead_id:body.leadId,course:data.course});status.textContent='Заявка принята. Продолжите в WhatsApp — сообщение уже подготовлено.';
  fallback.textContent='Продолжить в WhatsApp ↗︎';submit.hidden=true;
 }catch{status.textContent='Сейчас можно записаться напрямую в WhatsApp. Отправьте подготовленное сообщение — администратор ответит вам.';fallback.textContent='Отправить заявку в WhatsApp ↗︎';}
 finally{busy=false;submit.disabled=false;fallback.href=url;fallback.hidden=false;fallback.focus();}
});
