const tabs=[...document.querySelectorAll('[data-program]')];
function selectProgram(index,focus=false){const p=programs[index];if(!p)return;tabs.forEach((t,i)=>{t.setAttribute('aria-selected',String(i===index));t.tabIndex=i===index?0:-1});if(focus)tabs[index].focus();$('#course-panel').setAttribute('aria-labelledby','tab-'+index);$('#course-tag').textContent=p.tag;$('#course-heading').textContent=p.heading;$('#course-text').textContent=p.text;$('#course-word').textContent=p.accent;$('#course-book').dataset.book=p.name;$('#course-list').replaceChildren(...p.items.map((item,i)=>{const row=document.createElement('div'),num=document.createElement('small'),text=document.createElement('span'),check=document.createElement('b');num.textContent='0'+(i+1);text.textContent=item;check.textContent='✓';row.append(num,text,check);return row;}));}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectProgram(i));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectProgram(next,true)}})});

const journeyReminder=$('#journey-reminder');
let journeyDismissTimer;
function hideJourneyReminder(){journeyReminder.hidden=true;clearTimeout(journeyDismissTimer);}
function autoHideJourneyReminder(){clearTimeout(journeyDismissTimer);journeyDismissTimer=setTimeout(()=>{if(journeyReminder.contains(document.activeElement)||journeyReminder.matches(':hover'))autoHideJourneyReminder();else hideJourneyReminder();},20000);}
function journeyReminderBlocked(){return document.hidden||Boolean(document.querySelector('dialog[open],#consultation-submit:disabled,#submit-booking:disabled'))||Boolean(document.activeElement?.closest('input,textarea,select,#booking-form,#consultation-form,#admission-quiz'));}
function startJourneyReminderSchedule(){return createJourneyReminderSchedule({isBlocked:journeyReminderBlocked,show(){if(!journeyReminder.hidden)return;journeyReminder.hidden=false;autoHideJourneyReminder();event('journey_reminder_shown');}});}
let journeyReminderSchedule=startJourneyReminderSchedule();
addEventListener('pageshow',event=>{if(event.persisted){journeyReminderSchedule.stop();journeyReminderSchedule=startJourneyReminderSchedule();}});
$('#close-journey-reminder').addEventListener('click',hideJourneyReminder);
document.querySelectorAll('[data-reminder-link]').forEach(link=>link.addEventListener('click',()=>{hideJourneyReminder();event('journey_reminder_click',{target:link.getAttribute('href')});}));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!journeyReminder.hidden)hideJourneyReminder();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)hideJourneyReminder();});
document.addEventListener('focusin',()=>{if(journeyReminderBlocked())hideJourneyReminder();});
document.addEventListener('click',event=>{if(event.target.closest('[data-book],[data-consult-abroad],[data-start-admission]'))hideJourneyReminder();},true);
addEventListener('pagehide',()=>{journeyReminderSchedule.stop();clearTimeout(journeyDismissTimer);});

