const ADMISSION_OPTIONS=Object.freeze({
 role:['Школьник','Студент','Родитель'],
 stage:['Учусь в 8–9 классе','Учусь в 10–11 классе','Учусь в колледже','Учусь в университете','Уже окончил обучение'],
 country:['США','Великобритания','Канада','Европа','Азия','Пока не определился'],
 english:['A1','A2','B1','B2','C1 и выше','Не знаю'],
 intake:['В ближайший год','Через 1–2 года','Через 3 года и позже','Пока не определился'],
 funding:['Хочу получить грант','Рассматриваю платное обучение','Рассматриваю оба варианта','Нужна консультация']
});
const ADMISSION_LABELS=Object.freeze({role:'Кто обращается',stage:'Этап обучения',country:'Страна',english:'Уровень английского',intake:'Начало учёбы',funding:'Финансирование',year:'Год поступления',whatsapp:'Другой WhatsApp',milestone:'Интересующий этап'});
function cleanAdmission(input){
 const source=input&&typeof input==='object'&&!Array.isArray(input)?input:{},result={};
 for(const [key,options] of Object.entries(ADMISSION_OPTIONS))if(options.includes(source[key]))result[key]=source[key];
 if(/^20\d{2}$/.test(String(source.year||'')))result.year=String(source.year);
 if(/^\+[1-9]\d{9,14}$/.test(source.whatsapp||''))result.whatsapp=source.whatsapp;
 if(Number.isInteger(source.milestone)&&source.milestone>=1&&source.milestone<=12)result.milestone=source.milestone;
 return result;
}
function admissionLines(input){return Object.entries(cleanAdmission(input)).map(([key,value])=>`${ADMISSION_LABELS[key]}: ${value}`);}
function getAdmissionPlan(input){
 const profile=cleanAdmission(input),actions=[];
 actions.push(profile.english==='Не знаю'||!profile.english?'Определить уровень английского на диагностике.':['A1','A2'].includes(profile.english)?'Начать с General English и развивать базу для дальнейшей учёбы.':'Проверить академический английский и необходимость IELTS или других экзаменов.');
 actions.push(profile.country==='Пока не определился'||!profile.country?'Сравнить страны по программе, общему бюджету и языку обучения.':'Проверить программы, язык обучения, требования и полную стоимость в выбранной стране.');
 actions.push(profile.stage==='Учусь в университете'||profile.stage==='Уже окончил обучение'?'Уточнить цель: новая степень, магистратура или другой формат; проверить признание предыдущего образования.':'Проверить, какие оценки и документы нужны для выбранной программы после школы или колледжа.');
 actions.push(profile.funding==='Хочу получить грант'||profile.funding==='Рассматриваю оба варианта'?'Изучить условия грантов, сроки подачи и запасной бюджет: финансирование не гарантировано.':'Посчитать обучение, проживание, страховку, визу и другие расходы.');
 actions.push(profile.intake==='В ближайший год'?'В первую очередь проверить ближайшие дедлайны и доступные наборы.':'Составить календарь подготовки и подачи после проверки требований.');
 return {profile,actions,nextStep:'Записаться на консультацию и взять с собой оценки, сведения об английском и примерный бюджет.'};
}
// Pure model for a future authenticated adviser workspace. No public admin UI or server storage.
function buildConsultantRoadmap({profile={},completed=[],deadlines={},nextStep=''}={}){
 const ids=[...new Set(completed.filter(id=>Number.isInteger(id)&&id>=1&&id<=12))];
 const safeDeadlines=Object.fromEntries(Object.entries(deadlines).filter(([id,date])=>/^([1-9]|1[0-2])$/.test(id)&&/^\d{4}-\d{2}-\d{2}$/.test(date)));
 return {...getAdmissionPlan(profile),completed:ids,deadlines:safeDeadlines,nextStep:String(nextStep).replace(/[\u0000-\u001f\u007f]/g,'').slice(0,400)};
}

