const ABROAD_TRANSLATIONS=[...ABROAD_COPY,...ABROAD_QUESTIONS.map(q=>[q[1],q[2]]),...ABROAD_STAGES.flatMap(s=>['label','title','text','result','cta'].map(key=>[s[key],s.kk[key]]))];





