const abSelect=selector=>document.querySelector(selector);
function abElement(tag,text='',className=''){const node=document.createElement(tag);if(text)node.textContent=text;if(className)node.className=className;return node;}
function abEvent(event,extra={}){window.dataLayer=window.dataLayer||[];window.dataLayer.push({event,...extra});}
function abScroll(node){node.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
let abProfile={role:'Школьник'},abCurrent=1,abQuizStep=0,abVisited=new Set(),abBusy=false,abRequestId=crypto.randomUUID();
const abQuizForm=abSelect('#admission-quiz'),abDetails=abSelect('#milestone-details'),abResult=abSelect('#admission-result'),abForm=abSelect('#consultation-form');
const abRoleCopy=['Представь: после школы ты открываешь письмо от университета. До этого момента — понятные шаги на карте.','Представь: ты продолжаешь образование в другой стране. Сначала уточним программу и требования к твоему диплому.','Представьте первый день вашего ребёнка в новом кампусе. Начните с понятного плана, бюджета и требований.'];
function StudyAbroadHero(){document.querySelectorAll('[data-ab-role]').forEach((button,index)=>button.addEventListener('click',()=>{abProfile.role=ADMISSION_OPTIONS.role[index];abSelect('#consultation-role').value=abProfile.role;document.querySelectorAll('[data-ab-role]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));abSelect('#ab-role-story').textContent=abRoleCopy[index];if(!abResult.hidden)PersonalizedRoadmap();abEvent('abroad_role',{role:abProfile.role});}));}
function EnglishLevelProgress(){const fieldset=abElement('fieldset','','ab-levels'),legend=abElement('legend','Текущий уровень для примера');fieldset.append(legend);for(const code of ['A1','A2','B1','B2','C1','C2']){const button=abElement('button',code);button.type='button';button.setAttribute('aria-pressed',String(abProfile.english===code||code==='C1'&&abProfile.english==='C1 и выше'));button.addEventListener('click',()=>{abProfile.english=['C1','C2'].includes(code)?'C1 и выше':code;fieldset.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));});fieldset.append(button);}fieldset.append(abElement('small','Требуемый уровень зависит от университета и программы. Это не языковой тест.'));return fieldset;}
function MilestoneDetails(id,{focus=false}={}){
 abCurrent=id;const stage=ABROAD_STAGES[id-1];if(!stage)return;abVisited.add(id);
 document.querySelectorAll('[data-ab-stop]').forEach(button=>{const selected=Number(button.dataset.abStop)===id;button.setAttribute('aria-pressed',String(selected));button.classList.toggle('visited',abVisited.has(Number(button.dataset.abStop)));});
 abSelect('#ab-progress-count').textContent=`${abVisited.size} / 12`;
 const label=abElement('div',String(id).padStart(2,'0')+' / 12','ab-step-number'),title=abElement('h3',stage.title);title.id='ab-detail-title';title.tabIndex=-1;
 const outcome=abElement('div','','ab-outcome');outcome.append(abElement('small','Что получишь на этом шаге'),abElement('p',stage.result));
 const visual=abElement('figure','','ab-detail-visual'),illustration=document.createElement('img');illustration.src=({"/journey-icons/01.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-01.webp","/journey-icons/02.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-02.webp","/journey-icons/03.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-03.webp","/journey-icons/04.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-04.webp","/journey-icons/05.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-05.webp","/journey-icons/06.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-06.webp","/journey-icons/07.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-07.webp","/journey-icons/08.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-08.webp","/journey-icons/09.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-09.webp","/journey-icons/10.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-10.webp","/journey-icons/11.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-11.webp","/journey-icons/12.webp":"https://cdn.jsdelivr.net/gh/saleskeilee-source/smartclass.english@main/tilda/img/journey-12.webp"})['/journey-icons/'+String(id).padStart(2,'0')+'.webp'];illustration.alt='';illustration.width=512;illustration.height=512;visual.append(illustration);
 if(id===6||id===12)visual.append(abElement('figcaption',id===6?'Иллюстрация: кампус Оксфорда':'Иллюстрация: Harvard Yard, США'));
 const cta=abElement('button',stage.cta,'btn');cta.type='button';cta.addEventListener('click',()=>ConsultationCTA(id));
 const nav=abElement('div','','ab-detail-nav');for(const [direction,labelText] of [[-1,'Предыдущий этап'],[1,'Следующий этап']]){const button=abElement('button',labelText,'textlink');button.type='button';button.disabled=id+direction<1||id+direction>12;button.addEventListener('click',()=>MilestoneDetails(id+direction,{focus:true}));nav.append(button);}
 abDetails.replaceChildren(label,title,abElement('p',stage.text),outcome,visual,...(id===4?[EnglishLevelProgress()]:[]),cta,nav);
 if(focus)title.focus();
}
function JourneyMilestone(){document.querySelectorAll('[data-ab-stop]').forEach(button=>{button.addEventListener('click',()=>{MilestoneDetails(Number(button.dataset.abStop),{focus:true});abScroll(abDetails);abEvent('abroad_stop',{stage:abCurrent});});button.addEventListener('keydown',event=>{const ids={ArrowRight:1,ArrowDown:1,ArrowLeft:-1,ArrowUp:-1};if(event.key in ids){event.preventDefault();const next=Math.max(1,Math.min(12,Number(button.dataset.abStop)+ids[event.key]));abSelect(`[data-ab-stop="${next}"]`).focus();}});});}
function JourneyRoadmap(){MilestoneDetails(1);JourneyMilestone();}
function ConsultationCTA(id=abCurrent){if(abBusy)return;abProfile.milestone=id;const profileText=abElement('p');profileText.append(abElement('b','Интересующий этап'),document.createTextNode(': '),abElement('span',ABROAD_STAGES[id-1].label));abSelect('#consultation-context').replaceChildren(profileText);abSelect('#consultation-role').value=abProfile.role;abSelect('#consultation-country').value=abProfile.country||'Пока не определился';abSelect('#consultation').hidden=false;abScroll(abSelect('#consultation'));abSelect('#consultation-name').focus({preventScroll:true});abEvent('abroad_consultation_start',{stage:id});}
function AdmissionQuiz(){
 document.querySelectorAll('[data-start-admission]').forEach(button=>button.addEventListener('click',()=>{abQuizForm.hidden=false;abResult.hidden=true;abSelect('.ab-quiz-heading [data-start-admission]').hidden=true;renderAdmissionQuestion();abScroll(abSelect('#admission-quiz-section'));abEvent('abroad_quiz_start');}));
 abQuizForm.addEventListener('submit',event=>{event.preventDefault();const answer=abQuizForm.querySelector('input[name="admission-answer"]:checked');if(!answer){abSelect('#admission-quiz-error').textContent='Выбери один ответ, чтобы продолжить.';return;}const [key]=ABROAD_QUESTIONS[abQuizStep];abProfile[key]=answer.value;abRequestId=crypto.randomUUID();if(abQuizStep<4){abQuizStep++;renderAdmissionQuestion(true);}else{PersonalizedRoadmap();abQuizForm.hidden=true;abResult.hidden=false;abScroll(abResult);abResult.querySelector('h3').focus({preventScroll:true});abEvent('abroad_quiz_complete',{country:abProfile.country});}});
 abSelect('#admission-quiz-back').addEventListener('click',()=>{abQuizStep=Math.max(0,abQuizStep-1);renderAdmissionQuestion(true);});
}
function renderAdmissionQuestion(focus=false){
 const [key,title]=ABROAD_QUESTIONS[abQuizStep];abSelect('#admission-question-title').textContent=title;abSelect('#admission-question-count').textContent=`${abQuizStep+1} / 5`;abSelect('#admission-quiz-error').textContent='';
 abSelect('#admission-answers').replaceChildren(...ADMISSION_OPTIONS[key].map(value=>{const label=abElement('label','','ab-answer'),radio=document.createElement('input');radio.type='radio';radio.name='admission-answer';radio.value=value;radio.checked=abProfile[key]===value;label.append(radio,abElement('span',value));return label;}));
 abSelect('#admission-quiz-back').hidden=abQuizStep===0;abSelect('#admission-quiz-next').textContent=abQuizStep===4?'Показать мой маршрут':'Дальше';if(focus)abSelect('#admission-question-title').focus();
}
function PersonalizedRoadmap(){
 const plan=getAdmissionPlan(abProfile),heading=abElement('h3','Твой предварительный маршрут готов.');heading.tabIndex=-1;
 const start=abElement('div','','ab-profile-summary');start.append(abElement('h4','Твоя стартовая точка'),...admissionLines(plan.profile).filter(line=>!line.startsWith('Интересующий этап:')).map(line=>{const row=abElement('p');const index=line.indexOf(': ');row.append(abElement('b',line.slice(0,index)),document.createTextNode(': '),abElement('span',line.slice(index+2)));return row;}));
 const list=abElement('ol','','ab-plan-actions');plan.actions.forEach(text=>list.append(abElement('li',text)));
 const buttons=abElement('div','','ab-result-actions'),consult=abElement('button','Получить персональный план на консультации','btn'),edit=abElement('button','Изменить ответы','textlink'),download=abElement('button','Скачать мой план','textlink');
 for(const button of [consult,edit,download])button.type='button';consult.addEventListener('click',()=>ConsultationCTA());edit.addEventListener('click',()=>{abQuizStep=0;abResult.hidden=true;abQuizForm.hidden=false;renderAdmissionQuestion(true);});
 download.addEventListener('click',()=>{const lines=['SmartClass · Study Abroad Journey',translateText('Предварительный маршрут'),...admissionLines(plan.profile).map(line=>{const i=line.indexOf(': ');return translateText(line.slice(0,i))+': '+translateText(line.slice(i+2));}),...plan.actions.map((action,i)=>`${i+1}. ${translateText(action)}`),translateText(plan.nextStep)],blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='SmartClass-study-plan.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 buttons.append(consult,edit,download);abResult.replaceChildren(heading,abElement('p','На консультации уточним его с учётом оценок, английского, бюджета и требований университетов.'),start,abElement('h4','С чего начать'),list,abElement('h4','Ближайшее действие'),abElement('p',plan.nextStep),buttons);
}
function abAttribution(){let previous=null;try{previous=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')}catch{}return captureAttribution({url:location.href,referrer:document.referrer,cookies:document.cookie,previous});}
function abWhatsApp(data){const lines=['Здравствуйте! Хочу консультацию по поступлению за рубеж в SmartClass.',`Имя: ${data.name}`,`Код заявки: SC-${data.requestId.slice(0,8)}`,...admissionLines(data.admission),...getAdmissionPlan(data.admission).actions,...Object.entries(cleanTracking(data.tracking)).map(([key,value])=>`${key}: ${value}`),data.landing?`Страница: ${data.landing}`:''].filter(Boolean);return localizedWhatsApp('https://wa.me/77085427588?text='+encodeURIComponent(lines.join('\n')));}
function ConsultationForm(){
 for(const [id,key] of [['consultation-role','role'],['consultation-country','country']]){const select=abSelect('#'+id);select.replaceChildren(...ADMISSION_OPTIONS[key].map(value=>{const option=abElement('option',value);option.value=value;return option;}));}
 const year=abSelect('#consultation-year'),currentYear=new Date().getFullYear();for(let i=0;i<8;i++){const option=abElement('option',String(currentYear+i));option.value=String(currentYear+i);year.append(option);}
 document.querySelectorAll('[data-consult-abroad]').forEach(button=>button.addEventListener('click',()=>ConsultationCTA()));
 const status=abSelect('#consultation-status'),submit=abSelect('#consultation-submit'),wa=abSelect('#consultation-whatsapp');
 abForm.addEventListener('input',()=>{if(abBusy)return;abRequestId=crypto.randomUUID();wa.hidden=true;status.textContent='';submit.hidden=false;});
 abForm.addEventListener('submit',async event=>{
  event.preventDefault();if(abBusy||!abForm.reportValidity())return;const fd=new FormData(abForm),phone=normalizePhone(fd.get('phone')),other=String(fd.get('otherWhatsApp')||'').trim();
  if(!phone){status.textContent='Укажи корректный номер с кодом страны.';return;}if(other&&!normalizePhone(other)){status.textContent='Проверь дополнительный номер WhatsApp.';return;}
  const attribution=abAttribution(),data={requestId:abRequestId,phone,name:String(fd.get('name')||'').trim(),course:'Поступление',branch:'Байтерекова 100/3',consent:fd.get('consent')==='on',website:String(fd.get('website')||''),admission:cleanAdmission({...abProfile,role:fd.get('role'),country:fd.get('country'),year:fd.get('year'),whatsapp:other?normalizePhone(other):''}),tracking:attribution.last,firstTracking:attribution.first,landing:attribution.landing};
  const href=abWhatsApp(data);abBusy=true;submit.disabled=true;status.textContent='Отправляем заявку…';wa.hidden=true;
  try{const response=await fetch('/api/leads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(30000)}),result=await response.json();if(!response.ok||!result.ok)throw new Error('lead_unavailable');status.textContent='Заявка принята. Продолжи общение в WhatsApp.';submit.hidden=true;abEvent('abroad_lead_created',{lead_id:result.leadId});}
  catch{status.textContent='Не удалось отправить заявку. Отправь готовое сообщение в WhatsApp — после этого администратор подтвердит запись.';}
  finally{abBusy=false;submit.disabled=false;wa.href=href;wa.hidden=false;wa.focus();}
 });
 wa.addEventListener('click',()=>abEvent('whatsapp_click',{kind:'admission'}));
}
if(abSelect('#study-abroad')){StudyAbroadHero();JourneyRoadmap();AdmissionQuiz();ConsultationForm();}

